 {
  "name": "ugv.py",
  "desc": "Programa principal (Python 3)",
  "text": "#!/usr/bin/env python3\n\"\"\"Control del prototipo de orugas: la Raspberry Pi 3 Model B maneja directamente el puente H L298N.\n\nUn solo programa, sin dependencias fuera de lo que trae Raspberry Pi OS:\n  * servidor web para manejar el vehículo desde el celular (red Wi-Fi propia de la Raspberry Pi);\n  * control de los motores: PWM por hardware en GPIO 12 (ENA) y GPIO 13 (ENB),\n    sentido de giro en GPIO 17/27 (IN1/IN2, motor A izquierdo) y GPIO 22/23 (IN3/IN4, motor B derecho);\n  * recorridos programados por tramos de tiempo y velocidad, en lazo abierto;\n  * vigilancia: detiene los motores si dejan de llegar órdenes del celular durante TIMEOUT_MS;\n  * registro en CSV de cada orden, con el código de la prueba, la superficie y la carga.\n\nUso en la Raspberry Pi (ver README.md):   sudo python3 ugv.py\nUso en un computador, sin hardware:       python3 ugv.py --simular      (abre http://localhost:8080)\n\nLimitación declarada en el informe: si este programa o el sistema operativo se bloquean, los pines pueden\nquedar en su último estado. El corte total del prototipo es desconectar la batería.\n\"\"\"\nimport argparse\nimport collections\nimport csv\nimport json\nimport logging\nimport os\nimport re\nimport signal\nimport socket\nimport sys\nimport threading\nimport time\nfrom datetime import datetime\nfrom http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\nfrom urllib.parse import parse_qs, unquote, urlparse\n\nVERSION = \"1.0.0\"\nDIR = os.path.dirname(os.path.abspath(__file__))\n\n# ---------------------------------------------------------------- pines (numeración BCM) del diagrama final\nPIN_ENA, PIN_IN1, PIN_IN2 = 12, 17, 27   # motor A, oruga izquierda  (pines físicos 32, 11, 13)\nPIN_IN3, PIN_IN4, PIN_ENB = 22, 23, 13   # motor B, oruga derecha    (pines físicos 15, 16, 33)\nPWM_CANAL = {12: 0, 13: 1}               # GPIO 12 = PWM0, GPIO 13 = PWM1 (dtoverlay=pwm-2chan)\n\n# ---------------------------------------------------------------- configuración (se puede cambiar en config.json)\nCONFIG_DEF = {\n    \"puerto\": 80,           # http://10.42.0.1 desde el celular conectado a la red del vehículo\n    \"pwm_hz\": 1000,         # frecuencia de la PWM hacia ENA y ENB\n    \"timeout_ms\": 800,      # sin órdenes durante este tiempo -> parada (en el informe: \"____ ms\"; ajustar con las pruebas)\n    \"factor_izq\": 1.0,      # ajuste por software de cada motor si el vehículo se desvía en línea recta\n    \"factor_der\": 1.0,\n    \"toma_control_s\": 3.0,  # otro celular puede tomar el control si el actual no envía órdenes en este tiempo\n}\nTIPOS = {  # tipo de tramo -> sentido de (oruga izquierda, oruga derecha)\n    \"avanzar\": (1, 1), \"retroceder\": (-1, -1), \"izquierda\": (-1, 1), \"derecha\": (1, -1), \"pausa\": (0, 0),\n}\nMAX_TRAMOS, MAX_DURACION_S = 50, 60.0\nNOMBRE_OK = re.compile(r\"^[\\w\\- áéíóúñÁÉÍÓÚÑ]{1,40}$\")\n\nlog = logging.getLogger(\"ugv\")\n\n\ndef cargar_config(ruta):\n    cfg = dict(CONFIG_DEF)\n    if os.path.exists(ruta):\n        with open(ruta, encoding=\"utf-8\") as f:\n            cfg.update({k: v for k, v in json.load(f).items() if k in CONFIG_DEF})\n    return cfg\n\n\n# ================================================================ salidas\nclass PWMHardware:\n    \"\"\"PWM por hardware de la Raspberry Pi a través de /sys/class/pwm (requiere dtoverlay=pwm-2chan).\"\"\"\n\n    def __init__(self, gpio, hz):\n        self.canal = PWM_CANAL[gpio]\n        self.chip = self._buscar_chip()\n        self.base = f\"{self.chip}/pwm{self.canal}\"\n        if not os.path.isdir(self.base):\n            self._escribir(f\"{self.chip}/export\", self.canal)\n            for _ in range(50):                      # el sistema tarda un momento en crear los archivos\n                if os.access(f\"{self.base}/period\", os.W_OK):\n                    break\n                time.sleep(0.02)\n        self.periodo = int(1e9 / hz)\n        self._escribir(f\"{self.base}/enable\", 0)\n        self._escribir(f\"{self.base}/duty_cycle\", 0)\n        self._escribir(f\"{self.base}/period\", self.periodo)\n        self._escribir(f\"{self.base}/enable\", 1)\n\n    @staticmethod\n    def _buscar_chip():\n        raiz = \"/sys/class/pwm\"\n        for nombre in sorted(os.listdir(raiz)) if os.path.isdir(raiz) else []:\n            ruta = os.path.join(raiz, nombre)\n            try:\n                with open(os.path.join(ruta, \"npwm\")) as f:\n                    if int(f.read()) >= 2:\n                        return ruta\n            except OSError:\n                continue\n        raise RuntimeError(\"No hay PWM por hardware: agrega 'dtoverlay=pwm-2chan,pin=12,func=4,pin2=13,func2=4' \"\n                           \"y 'dtparam=audio=off' en config.txt y reinicia (ver README.md).\")\n\n    @staticmethod\n    def _escribir(ruta, valor):\n        with open(ruta, \"w\") as f:\n            f.write(str(valor))\n\n    def set(self, fraccion):\n        self._escribir(f\"{self.base}/duty_cycle\", int(self.periodo * max(0.0, min(1.0, fraccion))))\n\n    def close(self):\n        try:\n            self.set(0)\n            self._escribir(f\"{self.base}/enable\", 0)\n        except OSError:\n            pass\n\n\nclass PWMSoftware:\n    \"\"\"Respaldo si no está activo el overlay: PWM por software de gpiozero (menos estable).\"\"\"\n\n    def __init__(self, gpio, hz):\n        from gpiozero import PWMOutputDevice\n        self.dev = PWMOutputDevice(gpio, frequency=hz, initial_value=0)\n\n    def set(self, fraccion):\n        self.dev.value = max(0.0, min(1.0, fraccion))\n\n    def close(self):\n        self.dev.close()\n\n\nclass SalidaDigital:\n    def __init__(self, gpio):\n        from gpiozero import DigitalOutputDevice\n        self.dev = DigitalOutputDevice(gpio, initial_value=False)\n\n    def set(self, nivel):\n        self.dev.value = 1 if nivel else 0\n\n    def close(self):\n        self.dev.close()\n\n\nclass SalidaSimulada:\n    \"\"\"Para probar el programa en un computador: guarda el valor que tendría el pin.\"\"\"\n\n    def __init__(self, gpio, *_):\n        self.gpio, self.valor = gpio, 0\n\n    def set(self, valor):\n        self.valor = valor\n\n    def close(self):\n        self.valor = 0\n\n\n# ================================================================ motores\nclass Motores:\n    \"\"\"Traduce una orden (-100..100 por oruga) en el sentido de IN1..IN4 y el ancho de pulso de ENA/ENB.\"\"\"\n\n    def __init__(self, cfg, simular=False):\n        self.cfg = cfg\n        self.lock = threading.Lock()\n        self.izq = self.der = 0\n        if simular:\n            self.tipo_pwm = \"simulada\"\n            pwm, dig = SalidaSimulada, SalidaSimulada\n        else:\n            dig = SalidaDigital\n            try:\n                PWMHardware(PIN_ENA, cfg[\"pwm_hz\"]).close()   # comprobación\n                pwm, self.tipo_pwm = PWMHardware, \"hardware\"\n            except (RuntimeError, OSError) as e:\n                log.warning(\"%s Se usa PWM por software como respaldo.\", e)\n                pwm, self.tipo_pwm = PWMSoftware, \"software\"\n        self.ena, self.enb = pwm(PIN_ENA, cfg[\"pwm_hz\"]), pwm(PIN_ENB, cfg[\"pwm_hz\"])\n        self.in1, self.in2, self.in3, self.in4 = (dig(p) for p in (PIN_IN1, PIN_IN2, PIN_IN3, PIN_IN4))\n        self.parar()\n\n    @staticmethod\n    def _lado(en, ia, ib, valor, factor, anterior):\n        v = max(-100.0, min(100.0, float(valor) * factor))\n        if (v > 0) != (anterior > 0) or (v < 0) != (anterior < 0):\n            en.set(0)                   # si cambia el sentido, primero se quita la potencia,\n            ia.set(v > 0)               # luego se fija el sentido en INx,\n            ib.set(v < 0)\n        en.set(abs(v) / 100.0)          # y por último el ancho de pulso en ENx\n        return round(v)\n\n    def mover(self, izq, der):\n        with self.lock:\n            self.izq = self._lado(self.ena, self.in1, self.in2, izq, self.cfg[\"factor_izq\"], self.izq)\n            self.der = self._lado(self.enb, self.in3, self.in4, der, self.cfg[\"factor_der\"], self.der)\n\n    def parar(self):\n        with self.lock:\n            for s in (self.ena, self.enb, self.in1, self.in2, self.in3, self.in4):\n                s.set(0)\n            self.izq = self.der = 0\n\n    def pines(self):\n        \"\"\"Estado de los seis pines, para la página y las pruebas.\"\"\"\n        v = lambda s: getattr(s, \"valor\", None)\n        return {\"ENA\": v(self.ena), \"IN1\": v(self.in1), \"IN2\": v(self.in2),\n                \"IN3\": v(self.in3), \"IN4\": v(self.in4), \"ENB\": v(self.enb)}\n\n    def close(self):\n        self.parar()\n        for s in (self.ena, self.enb, self.in1, self.in2, self.in3, self.in4):\n            s.close()\n\n\n# ================================================================ registro CSV\nclass Registro:\n    COLS = [\"fecha_hora\", \"modo\", \"evento\", \"izq\", \"der\", \"prueba\", \"superficie\", \"carga_kg\"]\n\n    def __init__(self, carpeta):\n        self.carpeta = carpeta\n        os.makedirs(carpeta, exist_ok=True)\n        self.lock = threading.Lock()\n        self.ultimos = collections.deque(maxlen=200)\n        self.prueba = {\"codigo\": \"\", \"superficie\": \"\", \"carga_kg\": \"\"}\n\n    def archivo(self):\n        return os.path.join(self.carpeta, f\"registro-{datetime.now():%Y-%m-%d}.csv\")\n\n    def anotar(self, modo, evento, izq=0, der=0):\n        fila = {\"fecha_hora\": datetime.now().isoformat(timespec=\"milliseconds\"), \"modo\": modo, \"evento\": evento,\n                \"izq\": izq, \"der\": der, \"prueba\": self.prueba[\"codigo\"], \"superficie\": self.prueba[\"superficie\"],\n                \"carga_kg\": self.prueba[\"carga_kg\"]}\n        with self.lock:\n            nuevo = not os.path.exists(self.archivo())\n            with open(self.archivo(), \"a\", newline=\"\", encoding=\"utf-8\") as f:\n                w = csv.DictWriter(f, fieldnames=self.COLS)\n                if nuevo:\n                    w.writeheader()\n                w.writerow(fila)\n            self.ultimos.append(fila)\n\n\n# ================================================================ recorridos guardados\ndef validar_tramos(tramos):\n    if not isinstance(tramos, list) or not 1 <= len(tramos) <= MAX_TRAMOS:\n        raise ValueError(f\"El recorrido debe tener entre 1 y {MAX_TRAMOS} tramos.\")\n    limpios = []\n    for i, t in enumerate(tramos, 1):\n        if not isinstance(t, dict) or t.get(\"tipo\") not in TIPOS:\n            raise ValueError(f\"Tramo {i}: el tipo debe ser uno de {', '.join(TIPOS)}.\")\n        try:\n            vel, dur = float(t.get(\"velocidad\", 0)), float(t[\"duracion\"])\n        except (KeyError, TypeError, ValueError):\n            raise ValueError(f\"Tramo {i}: falta la duración o no es un número.\")\n        if not 0 <= vel <= 100:\n            raise ValueError(f\"Tramo {i}: la velocidad va de 0 a 100 %.\")\n        if not 0.1 <= dur <= MAX_DURACION_S:\n            raise ValueError(f\"Tramo {i}: la duración va de 0,1 a {MAX_DURACION_S:g} s.\")\n        limpios.append({\"tipo\": t[\"tipo\"], \"velocidad\": round(vel), \"duracion\": round(dur, 2)})\n    return limpios\n\n\nclass Recorridos:\n    EJEMPLO = {\"A-B-C\": [{\"tipo\": \"avanzar\", \"velocidad\": 60, \"duracion\": 4.0},\n                         {\"tipo\": \"pausa\", \"velocidad\": 0, \"duracion\": 1.0},\n                         {\"tipo\": \"derecha\", \"velocidad\": 60, \"duracion\": 1.2},\n                         {\"tipo\": \"avanzar\", \"velocidad\": 60, \"duracion\": 3.0},\n                         {\"tipo\": \"pausa\", \"velocidad\": 0, \"duracion\": 0.5}]}\n\n    def __init__(self, ruta):\n        self.ruta, self.lock = ruta, threading.Lock()\n        if not os.path.exists(ruta):\n            self._guardar(dict(self.EJEMPLO))\n\n    def todos(self):\n        with self.lock, open(self.ruta, encoding=\"utf-8\") as f:\n            return json.load(f)\n\n    def _guardar(self, datos):\n        tmp = self.ruta + \".tmp\"\n        with open(tmp, \"w\", encoding=\"utf-8\") as f:\n            json.dump(datos, f, ensure_ascii=False, indent=2)\n        os.replace(tmp, self.ruta)\n\n    def guardar(self, nombre, tramos):\n        if not NOMBRE_OK.match(nombre or \"\"):\n            raise ValueError(\"Nombre no válido (letras, números, espacios o guiones; máximo 40).\")\n        tramos = validar_tramos(tramos)\n        datos = self.todos()\n        with self.lock:\n            datos[nombre] = tramos\n            self._guardar(datos)\n        return tramos\n\n    def borrar(self, nombre):\n        datos = self.todos()\n        with self.lock:\n            if datos.pop(nombre, None) is None:\n                raise KeyError(nombre)\n            self._guardar(datos)\n\n\n# ================================================================ controlador (máquina de estados)\nESPERA, REMOTO, RECORRIDO, SEGURIDAD = \"ESPERA\", \"CONTROL REMOTO\", \"RECORRIDO PROGRAMADO\", \"DETENIDO POR SEGURIDAD\"\n\n\nclass OcupadoError(Exception):\n    pass\n\n\nclass Controlador:\n    def __init__(self, motores, registro, cfg):\n        self.m, self.reg, self.cfg = motores, registro, cfg\n        self.lock = threading.RLock()\n        self.modo = ESPERA\n        self.duenio, self.ultima = None, 0.0     # cliente con el control y hora de su última orden\n        self.rec = None                          # recorrido en curso (con su propio evento de parada)\n        self.vivo = True\n        self.vigia = threading.Thread(target=self._vigilar, name=\"vigilancia\", daemon=True)\n        self.vigia.start()\n\n    # ----- órdenes del celular\n    def _tomar(self, cliente):\n        ahora = time.monotonic()\n        if self.duenio and self.duenio != cliente and ahora - self.ultima < self.cfg[\"toma_control_s\"]:\n            raise OcupadoError(\"Otro dispositivo está manejando el vehículo.\")\n        if self.duenio != cliente:\n            self.reg.anotar(self.modo, \"toma de control\")\n        self.duenio, self.ultima = cliente, ahora\n\n    def mover(self, cliente, izq, der):\n        with self.lock:\n            if self.modo == RECORRIDO:\n                raise OcupadoError(\"Hay un recorrido en curso: deténgalo primero.\")\n            self._tomar(cliente)\n            antes = (self.m.izq, self.m.der)\n            self.m.mover(izq, der)\n            nuevo = REMOTO if (self.m.izq or self.m.der) else ESPERA\n            if (self.m.izq, self.m.der) != antes or nuevo != self.modo:\n                self.modo = nuevo\n                self.reg.anotar(self.modo, \"orden\", self.m.izq, self.m.der)\n\n    def latido(self, cliente):\n        with self.lock:\n            if cliente == self.duenio:\n                self.ultima = time.monotonic()\n\n    def parar(self, cliente=None, motivo=\"detener\"):\n        \"\"\"Cualquier dispositivo puede detener el vehículo, aunque no tenga el control.\"\"\"\n        with self.lock:\n            if self.rec:\n                self.rec[\"alto\"].set()\n                self.rec = None\n            self.m.parar()\n            if self.modo != ESPERA or motivo != \"detener\":\n                self.reg.anotar(self.modo, motivo)\n            self.modo = SEGURIDAD if motivo == \"sin órdenes\" else ESPERA\n\n    # ----- recorrido programado (lazo abierto: cumple tiempos y velocidades)\n    def ejecutar(self, cliente, nombre, tramos):\n        tramos = validar_tramos(tramos)\n        with self.lock:\n            if self.modo == RECORRIDO:\n                raise OcupadoError(\"Ya hay un recorrido en curso.\")\n            self._tomar(cliente)\n            self.modo = RECORRIDO\n            self.rec = {\"nombre\": nombre, \"tramos\": tramos, \"i\": 0, \"fin_tramo\": 0.0, \"alto\": threading.Event()}\n            self.reg.anotar(self.modo, f\"inicio de recorrido {nombre}\")\n        threading.Thread(target=self._correr, args=(self.rec,), name=\"recorrido\", daemon=True).start()\n\n    def _correr(self, rec):\n        for i, t in enumerate(rec[\"tramos\"]):\n            sl, sr = TIPOS[t[\"tipo\"]]\n            with self.lock:\n                if rec[\"alto\"].is_set():\n                    return\n                rec[\"i\"], rec[\"fin_tramo\"] = i, time.monotonic() + t[\"duracion\"]\n                self.m.mover(sl * t[\"velocidad\"], sr * t[\"velocidad\"])\n                self.reg.anotar(self.modo, f\"tramo {i + 1}: {t['tipo']}\", self.m.izq, self.m.der)\n            if rec[\"alto\"].wait(t[\"duracion\"]):\n                return\n        with self.lock:\n            if not rec[\"alto\"].is_set():\n                self.m.parar()\n                self.reg.anotar(self.modo, \"fin de recorrido\")\n                self.modo, self.rec = ESPERA, None\n\n    # ----- vigilancia: parada si dejan de llegar órdenes o latidos\n    def _vigilar(self):\n        while self.vivo:\n            time.sleep(0.02)\n            with self.lock:\n                moviendo = self.m.izq or self.m.der or self.modo == RECORRIDO\n                sin_ordenes = (time.monotonic() - self.ultima) * 1000 > self.cfg[\"timeout_ms\"]\n                if moviendo and sin_ordenes:\n                    log.warning(\"Sin órdenes durante %d ms: motores detenidos.\", self.cfg[\"timeout_ms\"])\n                    self.parar(motivo=\"sin órdenes\")\n\n    def estado(self, cliente=None):\n        with self.lock:\n            r = None\n            if self.rec and self.modo == RECORRIDO:\n                t = self.rec[\"tramos\"][self.rec[\"i\"]]\n                r = {\"nombre\": self.rec[\"nombre\"], \"tramo\": self.rec[\"i\"] + 1, \"total\": len(self.rec[\"tramos\"]),\n                     \"tipo\": t[\"tipo\"], \"restante_s\": round(max(0.0, self.rec[\"fin_tramo\"] - time.monotonic()), 1)}\n            return {\"version\": VERSION, \"modo\": self.modo, \"izq\": self.m.izq, \"der\": self.m.der,\n                    \"tienes_control\": cliente is not None and cliente == self.duenio, \"recorrido\": r,\n                    \"timeout_ms\": self.cfg[\"timeout_ms\"], \"pwm\": self.m.tipo_pwm, \"pines\": self.m.pines(),\n                    \"prueba\": self.reg.prueba}\n\n    def cerrar(self):\n        self.vivo = False\n        self.parar(motivo=\"programa detenido\")\n        self.m.close()\n\n\n# ================================================================ servidor web\nclass Servidor(BaseHTTPRequestHandler):\n    server_version = \"UGV-Orugas/\" + VERSION\n    ctl = recorridos = registro = cfg = None   # se asignan al arrancar\n\n    def log_message(self, fmt, *args):\n        log.debug(\"%s %s\", self.address_string(), fmt % args)\n\n    def _enviar(self, codigo, cuerpo, tipo=\"application/json; charset=utf-8\", extra=None):\n        datos = cuerpo if isinstance(cuerpo, bytes) else json.dumps(cuerpo, ensure_ascii=False).encode(\"utf-8\")\n        self.send_response(codigo)\n        self.send_header(\"Content-Type\", tipo)\n        self.send_header(\"Content-Length\", str(len(datos)))\n        self.send_header(\"Cache-Control\", \"no-store\")\n        for k, v in (extra or {}).items():\n            self.send_header(k, v)\n        self.end_headers()\n        self.wfile.write(datos)\n\n    def _json(self):\n        n = int(self.headers.get(\"Content-Length\") or 0)\n        if n > 65536:\n            raise ValueError(\"Petición demasiado grande.\")\n        return json.loads(self.rfile.read(n) or b\"{}\")\n\n    def do_GET(self):\n        u = urlparse(self.path)\n        q = parse_qs(u.query)\n        if u.path in (\"/\", \"/index.html\"):\n            with open(os.path.join(DIR, \"web\", \"index.html\"), \"rb\") as f:\n                return self._enviar(200, f.read(), \"text/html; charset=utf-8\")\n        if u.path == \"/api/estado\":\n            return self._enviar(200, self.ctl.estado((q.get(\"cliente\") or [None])[0]))\n        if u.path == \"/api/recorridos\":\n            return self._enviar(200, self.recorridos.todos())\n        if u.path == \"/api/registro\":\n            n = min(200, int((q.get(\"n\") or [\"30\"])[0]))\n            return self._enviar(200, list(self.registro.ultimos)[-n:])\n        if u.path == \"/registro.csv\":\n            ruta = self.registro.archivo()\n            datos = b\"\"\n            if os.path.exists(ruta):\n                with open(ruta, \"rb\") as f:\n                    datos = f.read()\n            return self._enviar(200, datos, \"text/csv; charset=utf-8\",\n                                {\"Content-Disposition\": f'attachment; filename=\"{os.path.basename(ruta)}\"'})\n        self._enviar(404, {\"error\": \"No existe.\"})\n\n    def do_POST(self):\n        u = urlparse(self.path)\n        try:\n            d = self._json()\n            cliente = str(d.get(\"cliente\") or \"\")[:64] or None\n            if u.path == \"/api/mover\":\n                self.ctl.mover(cliente, float(d.get(\"izq\", 0)), float(d.get(\"der\", 0)))\n            elif u.path == \"/api/parar\":\n                self.ctl.parar(cliente)\n            elif u.path == \"/api/latido\":\n                self.ctl.latido(cliente)\n            elif u.path == \"/api/recorridos\":\n                self.recorridos.guardar(str(d.get(\"nombre\", \"\")).strip(), d.get(\"tramos\"))\n            elif u.path == \"/api/ejecutar\":\n                nombre = str(d.get(\"nombre\") or \"sin nombre\")\n                tramos = d.get(\"tramos\") if \"tramos\" in d else self.recorridos.todos().get(nombre)\n                if tramos is None:\n                    raise KeyError(nombre)\n                self.ctl.ejecutar(cliente, nombre, tramos)\n            elif u.path == \"/api/prueba\":\n                self.registro.prueba = {\"codigo\": str(d.get(\"codigo\", \"\"))[:20], \"superficie\": str(d.get(\"superficie\", \"\"))[:20],\n                                        \"carga_kg\": str(d.get(\"carga_kg\", \"\"))[:6]}\n                self.registro.anotar(self.ctl.modo, \"datos de la prueba\")\n            else:\n                return self._enviar(404, {\"error\": \"No existe.\"})\n            self._enviar(200, self.ctl.estado(cliente))\n        except OcupadoError as e:\n            self._enviar(409, {\"error\": str(e)})\n        except KeyError as e:\n            self._enviar(404, {\"error\": f\"No existe el recorrido {e}.\"})\n        except (ValueError, TypeError) as e:\n            self._enviar(400, {\"error\": str(e)})\n\n    def do_DELETE(self):\n        u = urlparse(self.path)\n        if u.path.startswith(\"/api/recorridos/\"):\n            try:\n                self.recorridos.borrar(unquote(u.path.split(\"/\", 3)[3]))\n                return self._enviar(200, {\"ok\": True})\n            except KeyError:\n                return self._enviar(404, {\"error\": \"No existe ese recorrido.\"})\n        self._enviar(404, {\"error\": \"No existe.\"})\n\n\nclass ServidorWeb(ThreadingHTTPServer):\n    \"\"\"Escucha en IPv4 e IPv6 a la vez (si el sistema lo permite), para que 'localhost' responda sin demoras.\"\"\"\n    daemon_threads = True\n\n    def __init__(self, puerto, manejador):\n        doble = socket.has_dualstack_ipv6()\n        self.address_family = socket.AF_INET6 if doble else socket.AF_INET\n        super().__init__((\"::\" if doble else \"0.0.0.0\", puerto), manejador)\n\n    def server_bind(self):\n        if self.address_family == socket.AF_INET6:\n            self.socket.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 0)\n        super().server_bind()\n\n\ndef crear(simular=False, puerto=None, carpeta=DIR):\n    \"\"\"Arma el controlador y el servidor (lo usan main() y las pruebas).\"\"\"\n    cfg = cargar_config(os.path.join(carpeta, \"config.json\"))\n    motores = Motores(cfg, simular=simular)\n    registro = Registro(os.path.join(carpeta, \"registros\"))\n    ctl = Controlador(motores, registro, cfg)\n    Servidor.ctl, Servidor.registro, Servidor.cfg = ctl, registro, cfg\n    Servidor.recorridos = Recorridos(os.path.join(carpeta, \"recorridos.json\"))\n    srv = ServidorWeb(cfg[\"puerto\"] if puerto is None else puerto, Servidor)\n    return srv, ctl\n\n\ndef main():\n    ap = argparse.ArgumentParser(description=\"Control del prototipo de orugas (Raspberry Pi 3 + L298N).\")\n    ap.add_argument(\"--simular\", action=\"store_true\", help=\"probar sin hardware (pines simulados)\")\n    ap.add_argument(\"--puerto\", type=int, help=\"puerto web (por defecto 80; 8080 al simular)\")\n    ap.add_argument(\"-v\", \"--detalle\", action=\"store_true\", help=\"mostrar cada petición\")\n    a = ap.parse_args()\n    logging.basicConfig(level=logging.DEBUG if a.detalle else logging.INFO, format=\"%(asctime)s %(levelname)s %(message)s\")\n    srv, ctl = crear(a.simular, a.puerto if a.puerto else (8080 if a.simular else None))\n    detener = lambda *_: threading.Thread(target=srv.shutdown, daemon=True).start()\n    signal.signal(signal.SIGTERM, detener)\n    signal.signal(signal.SIGINT, detener)\n    log.info(\"UGV %s listo: PWM %s, parada sin órdenes a los %d ms, http://<ip-de-la-raspberry>:%d\",\n             VERSION, ctl.m.tipo_pwm, ctl.cfg[\"timeout_ms\"], srv.server_address[1])\n    ctl.reg.anotar(ESPERA, \"programa iniciado\")\n    try:\n        srv.serve_forever(poll_interval=0.2)\n    finally:\n        ctl.cerrar()\n        srv.server_close()\n        log.info(\"Programa detenido: motores apagados.\")\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"
 },
 {
  "name": "web/index.html",
  "desc": "Página de control del celular",
  "text": "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover, user-scalable=no\">\n<meta name=\"theme-color\" content=\"#14171a\">\n<title>UGV de orugas · control</title>\n<style>\n:root { --bg: #f3f1ea; --panel: #fff; --fg: #1b1d1f; --muted: #6b6f74; --line: #d9d6cc; --accent: #1f9a6c; --stop: #c8261d; --warn: #c98a0c; --r: 14px; }\n@media (prefers-color-scheme: dark) { :root { --bg: #121416; --panel: #1c1f22; --fg: #eceae4; --muted: #9aa0a6; --line: #30343a; --accent: #2fbf87; } }\n* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\nbody { margin: 0; background: var(--bg); color: var(--fg); font: 15px/1.4 system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif; padding: 0 0 96px; }\nheader { position: sticky; top: 0; z-index: 3; display: flex; align-items: center; gap: 10px; padding: 10px 16px; background: var(--panel); border-bottom: 1px solid var(--line); }\nheader h1 { font-size: 16px; margin: 0; flex: 1; }\n.pill { font: 600 12px ui-monospace, monospace; padding: 4px 10px; border-radius: 99px; border: 1px solid var(--line); white-space: nowrap; }\n.pill.ok { color: var(--accent); border-color: var(--accent); } .pill.bad { color: var(--stop); border-color: var(--stop); } .pill.run { background: var(--accent); color: #fff; border-color: var(--accent); }\nmain { max-width: 560px; margin: 0 auto; padding: 12px 16px; display: grid; gap: 12px; }\nsection { background: var(--panel); border: 1px solid var(--line); border-radius: var(--r); padding: 12px; }\nh2 { font-size: 14px; margin: 0 0 8px; text-transform: uppercase; letter-spacing: .05em; color: var(--muted); }\n.aviso { display: none; padding: 10px 12px; border-radius: 10px; background: color-mix(in srgb, var(--warn) 18%, var(--panel)); border: 1px solid var(--warn); font-size: 14px; }\n.aviso.show { display: block; }\n.pad { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; max-width: 330px; margin: 4px auto 10px; touch-action: none; user-select: none; -webkit-user-select: none; }\n.pad button { aspect-ratio: 1; font-size: 34px; border-radius: 18px; border: 1px solid var(--line); background: var(--bg); color: var(--fg); touch-action: none; }\n.pad button.on { background: var(--accent); color: #fff; border-color: var(--accent); }\n.pad .alto { font-size: 15px; font-weight: 700; background: var(--stop); color: #fff; border-color: var(--stop); }\n.pad .vacio { visibility: hidden; }\nlabel { display: block; font-size: 13px; color: var(--muted); margin: 6px 0 4px; }\ninput[type=range] { width: 100%; accent-color: var(--accent); }\n.fila { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }\n.fila > * { flex: 1 1 auto; }\nbutton.b { padding: 10px 12px; border-radius: 10px; border: 1px solid var(--line); background: var(--bg); color: var(--fg); font: 600 14px inherit; font-family: inherit; }\nbutton.b.go { background: var(--accent); color: #fff; border-color: var(--accent); }\nselect, input[type=number], input[type=text] { width: 100%; padding: 8px; border-radius: 8px; border: 1px solid var(--line); background: var(--bg); color: var(--fg); font: inherit; }\ntable { width: 100%; border-collapse: collapse; font-size: 14px; }\ntd, th { padding: 4px 3px; text-align: left; vertical-align: middle; } th { font-size: 12px; color: var(--muted); font-weight: 600; }\ntd.n { width: 22px; color: var(--muted); font: 12px ui-monospace, monospace; } td.x { width: 34px; }\ntr.cur td { background: color-mix(in srgb, var(--accent) 18%, transparent); }\n.barras { display: grid; grid-template-columns: auto 1fr 44px; gap: 6px 8px; align-items: center; font-size: 13px; }\n.barra { height: 10px; background: var(--bg); border: 1px solid var(--line); border-radius: 99px; position: relative; overflow: hidden; }\n.barra i { position: absolute; top: 0; bottom: 0; background: var(--accent); }\n.mono { font-family: ui-monospace, monospace; font-size: 12.5px; }\n.reg { max-height: 180px; overflow: auto; font: 12px/1.5 ui-monospace, monospace; color: var(--muted); }\n.parar { position: fixed; left: 16px; right: 16px; bottom: max(14px, env(safe-area-inset-bottom)); z-index: 4; padding: 18px; border: 0; border-radius: 16px; background: var(--stop); color: #fff; font: 800 20px inherit; font-family: inherit; letter-spacing: .08em; box-shadow: 0 6px 20px rgba(0,0,0,.25); max-width: 528px; margin: 0 auto; }\n.toast { position: fixed; left: 50%; bottom: 96px; transform: translateX(-50%); background: var(--fg); color: var(--bg); padding: 8px 14px; border-radius: 10px; font-size: 14px; opacity: 0; transition: opacity .2s; pointer-events: none; max-width: 90vw; z-index: 5; }\n.toast.show { opacity: 1; }\nsmall { color: var(--muted); }\n</style>\n</head>\n<body>\n<header><h1>UGV de orugas</h1><span class=\"pill\" id=\"conn\">conectando…</span><span class=\"pill\" id=\"modo\">—</span></header>\n<main>\n  <div class=\"aviso\" id=\"aviso\"></div>\n\n  <section>\n    <h2>Control remoto</h2>\n    <div class=\"pad\" id=\"pad\">\n      <span class=\"vacio\"></span><button data-d=\"adelante\" aria-label=\"Avanzar\">▲</button><span class=\"vacio\"></span>\n      <button data-d=\"izquierda\" aria-label=\"Girar a la izquierda\">◀</button><button class=\"alto\" data-d=\"alto\">ALTO</button><button data-d=\"derecha\" aria-label=\"Girar a la derecha\">▶</button>\n      <span class=\"vacio\"></span><button data-d=\"atras\" aria-label=\"Retroceder\">▼</button><span class=\"vacio\"></span>\n    </div>\n    <label for=\"vel\">Velocidad máxima: <b id=\"velTxt\">60 %</b></label>\n    <input type=\"range\" id=\"vel\" min=\"20\" max=\"100\" step=\"5\" value=\"60\">\n    <div class=\"barras\" style=\"margin-top:10px\">\n      <span>Motor A (izq.)</span><div class=\"barra\"><i id=\"bA\"></i></div><span class=\"mono\" id=\"vA\">0</span>\n      <span>Motor B (der.)</span><div class=\"barra\"><i id=\"bB\"></i></div><span class=\"mono\" id=\"vB\">0</span>\n    </div>\n    <p><small>Mantén pulsada una flecha para moverte; al soltarla el vehículo se detiene. Si el celular deja de enviar órdenes durante <span id=\"tmo\">800</span> ms, la Raspberry Pi detiene los motores. En un computador también sirven las flechas del teclado y la barra espaciadora.</small></p>\n  </section>\n\n  <section>\n    <h2>Recorrido programado</h2>\n    <div class=\"fila\"><select id=\"lista\" aria-label=\"Recorridos guardados\"></select><button class=\"b\" id=\"bCargar\">Abrir</button></div>\n    <table style=\"margin-top:8px\"><thead><tr><th></th><th>Tramo</th><th>Vel. %</th><th>Dur. s</th><th></th></tr></thead><tbody id=\"tramos\"></tbody></table>\n    <p class=\"mono\" id=\"total\"></p>\n    <div class=\"fila\"><button class=\"b\" id=\"bAgregar\">+ Tramo</button><button class=\"b\" id=\"bGuardar\">Guardar</button><button class=\"b\" id=\"bBorrar\">Borrar</button></div>\n    <div class=\"fila\" style=\"margin-top:8px\"><button class=\"b go\" id=\"bEjecutar\">▶ Ejecutar recorrido</button></div>\n    <div class=\"fila\" style=\"margin-top:8px\"><button class=\"b\" id=\"bExportar\">Exportar JSON</button><button class=\"b\" id=\"bImportar\">Importar JSON</button><input type=\"file\" id=\"archivo\" accept=\"application/json,.json\" hidden></div>\n    <p><small>El vehículo cumple cada tramo durante el tiempo indicado, sin medir su posición (lazo abierto). Mientras se ejecuta, esta página debe seguir abierta: si se cierra o se pierde el Wi-Fi, el vehículo se detiene.</small></p>\n  </section>\n\n  <section>\n    <h2>Datos de la prueba</h2>\n    <div class=\"fila\">\n      <div><label for=\"pCod\">Prueba</label><select id=\"pCod\"><option></option><option>P1</option><option>P2</option><option>P3</option><option>P4</option><option>P5</option><option>P6</option><option>P7</option><option>P8</option><option>P9</option><option>P10</option></select></div>\n      <div><label for=\"pSup\">Superficie</label><select id=\"pSup\"><option></option><option>banco</option><option>firme</option><option>tierra</option><option>arena</option><option>rampa</option></select></div>\n      <div><label for=\"pCar\">Carga (kg)</label><select id=\"pCar\"><option></option><option>0</option><option>1</option><option>2</option></select></div>\n    </div>\n    <div class=\"fila\" style=\"margin-top:8px\"><button class=\"b\" id=\"bPrueba\">Anotar en el registro</button><button class=\"b\" id=\"bCsv\">Descargar registro (CSV)</button></div>\n  </section>\n\n  <section>\n    <h2>Registro</h2>\n    <div class=\"reg\" id=\"reg\"></div>\n    <p class=\"mono\" id=\"info\"></p>\n  </section>\n</main>\n<button class=\"parar\" id=\"parar\">PARAR</button>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script>\n'use strict';\nconst $ = id => document.getElementById(id);\nconst CLIENTE = (() => { try { let c = sessionStorage.getItem('ugv-cliente'); if (!c) { c = Math.random().toString(36).slice(2, 12); sessionStorage.setItem('ugv-cliente', c); } return c; } catch (_) { return Math.random().toString(36).slice(2, 12); } })();\nconst TIPOS = { avanzar: 'Avanzar', retroceder: 'Retroceder', izquierda: 'Girar a la izq.', derecha: 'Girar a la der.', pausa: 'Pausa' };\nconst DIR = { adelante: [1, 1], atras: [-1, -1], izquierda: [-1, 1], derecha: [1, -1] };\nlet est = null, held = null, holdT = null, toastT = null;\n\nfunction toast(t) { const e = $('toast'); e.textContent = t; e.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => e.classList.remove('show'), 2600); }\nasync function api(path, body, method = 'POST') {\n  const r = await fetch(path, { method, headers: { 'Content-Type': 'application/json' }, body: body ? JSON.stringify(Object.assign({ cliente: CLIENTE }, body)) : undefined, keepalive: true, cache: 'no-store' });\n  const d = await r.json().catch(() => ({}));\n  if (!r.ok) throw new Error(d.error || 'Error ' + r.status);\n  return d;\n}\n\n/* ---------- control remoto: mantener pulsado ---------- */\nfunction enviar() {\n  if (!held) return;\n  const v = +$('vel').value, [a, b] = DIR[held];\n  api('/api/mover', { izq: a * v, der: b * v }).then(pintar).catch(e => { soltar(false); toast(e.message); });\n}\nfunction pulsar(d) {\n  if (d === 'alto') { parar(); return; }\n  if (held === d) return;\n  held = d; marcar(); enviar(); clearInterval(holdT); holdT = setInterval(enviar, 100);\n}\nfunction soltar(mandarParar = true) {\n  if (!held) return;\n  held = null; marcar(); clearInterval(holdT);\n  if (mandarParar) api('/api/parar', {}).then(pintar).catch(() => { });\n}\nfunction parar() { held = null; marcar(); clearInterval(holdT); api('/api/parar', {}).then(pintar).catch(e => toast(e.message)); }\nfunction marcar() { document.querySelectorAll('#pad button').forEach(b => b.classList.toggle('on', b.dataset.d === held)); }\ndocument.querySelectorAll('#pad button').forEach(b => {\n  b.addEventListener('pointerdown', e => { e.preventDefault(); b.setPointerCapture(e.pointerId); pulsar(b.dataset.d); });\n  ['pointerup', 'pointercancel', 'lostpointercapture'].forEach(ev => b.addEventListener(ev, () => { if (held === b.dataset.d) soltar(); }));\n  b.addEventListener('contextmenu', e => e.preventDefault());\n});\nconst TECLAS = { ArrowUp: 'adelante', w: 'adelante', ArrowDown: 'atras', s: 'atras', ArrowLeft: 'izquierda', a: 'izquierda', ArrowRight: 'derecha', d: 'derecha' };\naddEventListener('keydown', e => { if (/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)) return; if (e.key === ' ') { e.preventDefault(); parar(); return; }\n  const d = TECLAS[e.key]; if (d && !e.repeat) { e.preventDefault(); pulsar(d); } });\naddEventListener('keyup', e => { if (TECLAS[e.key] && held === TECLAS[e.key]) soltar(); });\ndocument.addEventListener('visibilitychange', () => { if (document.hidden) soltar(); });\naddEventListener('blur', () => soltar());\n$('parar').addEventListener('click', parar);\n$('vel').addEventListener('input', e => { $('velTxt').textContent = e.target.value + ' %'; });\n\n/* ---------- estado ---------- */\nfunction barra(el, v) { el.style.left = (v < 0 ? 50 + v / 2 : 50) + '%'; el.style.width = Math.abs(v) / 2 + '%'; }\nfunction pintar(d) {\n  est = d; const m = $('modo'); m.textContent = d.modo; m.className = 'pill ' + (d.modo.startsWith('DETENIDO') ? 'bad' : d.modo === 'ESPERA' ? '' : 'run');\n  barra($('bA'), d.izq); barra($('bB'), d.der); $('vA').textContent = d.izq; $('vB').textContent = d.der; $('tmo').textContent = d.timeout_ms;\n  const av = $('aviso'); let txt = '';\n  if (d.modo.startsWith('DETENIDO')) txt = 'El vehículo se detuvo porque dejaron de llegar órdenes. Vuelve a pulsar una flecha para continuar.';\n  else if (d.recorrido) txt = `Recorrido «${d.recorrido.nombre}»: tramo ${d.recorrido.tramo} de ${d.recorrido.total} (${TIPOS[d.recorrido.tipo]}), faltan ${d.recorrido.restante_s.toFixed(1)} s.` + (d.tienes_control ? '' : ' Lo maneja otro dispositivo.');\n  av.textContent = txt; av.classList.toggle('show', !!txt);\n  $('info').textContent = `PWM ${d.pwm} · versión ${d.version}`;\n  const i = d.recorrido && d.tienes_control ? d.recorrido.tramo - 1 : -1;\n  document.querySelectorAll('#tramos tr').forEach((tr, k) => tr.classList.toggle('cur', k === i));\n}\nlet fallos = 0;\nasync function consultar() {\n  try { const r = await fetch('/api/estado?cliente=' + CLIENTE, { cache: 'no-store' }); pintar(await r.json()); fallos = 0; $('conn').textContent = 'conectado'; $('conn').className = 'pill ok'; }\n  catch (_) { if (++fallos > 1) { $('conn').textContent = 'sin conexión'; $('conn').className = 'pill bad'; } }\n}\nsetInterval(consultar, 300); consultar();\n// latido mientras corre un recorrido iniciado desde este dispositivo\nfunction latir() { if (est && est.recorrido && est.tienes_control) api('/api/latido', {}).then(d => { if (!d.recorrido) pintar(d); }).catch(() => { }); }\nsetInterval(latir, 100);\n\n/* ---------- recorridos ---------- */\nlet guardados = {};\nfunction fila(t = { tipo: 'avanzar', velocidad: 60, duracion: 2 }) {\n  const tr = document.createElement('tr');\n  tr.innerHTML = `<td class=\"n\"></td><td><select>${Object.entries(TIPOS).map(([k, v]) => `<option value=\"${k}\" ${k === t.tipo ? 'selected' : ''}>${v}</option>`).join('')}</select></td>\n    <td><input type=\"number\" min=\"0\" max=\"100\" step=\"5\" value=\"${t.velocidad}\" inputmode=\"numeric\"></td><td><input type=\"number\" min=\"0.1\" max=\"60\" step=\"0.1\" value=\"${t.duracion}\" inputmode=\"decimal\"></td>\n    <td class=\"x\"><button class=\"b\" title=\"Quitar tramo\">✕</button></td>`;\n  const sel = tr.querySelector('select'), vel = tr.querySelector('input');\n  const sync = () => { vel.disabled = sel.value === 'pausa'; if (vel.disabled) vel.value = 0; total(); };\n  sel.addEventListener('change', sync); tr.querySelectorAll('input').forEach(i => i.addEventListener('input', total));\n  tr.querySelector('button').addEventListener('click', () => { tr.remove(); total(); });\n  $('tramos').appendChild(tr); sync();\n}\nfunction leer() { return [...$('tramos').querySelectorAll('tr')].map(tr => { const [vel, dur] = tr.querySelectorAll('input'); return { tipo: tr.querySelector('select').value, velocidad: +vel.value, duracion: +dur.value }; }); }\nfunction mostrar(tramos) { $('tramos').innerHTML = ''; tramos.forEach(fila); total(); }\nfunction total() { const t = leer(); document.querySelectorAll('#tramos td.n').forEach((td, i) => td.textContent = i + 1);\n  $('total').textContent = `${t.length} tramos · ${t.reduce((s, x) => s + (+x.duracion || 0), 0).toFixed(1)} s en total`; }\nasync function listar(sel) {\n  guardados = await (await fetch('/api/recorridos', { cache: 'no-store' })).json();\n  $('lista').innerHTML = Object.keys(guardados).map(n => `<option>${n.replace(/</g, '&lt;')}</option>`).join('');\n  if (sel) $('lista').value = sel;\n}\n$('bCargar').addEventListener('click', () => { const n = $('lista').value; if (guardados[n]) mostrar(guardados[n]); });\n$('bAgregar').addEventListener('click', () => { fila(); total(); });\n$('bGuardar').addEventListener('click', async () => { const n = prompt('Nombre del recorrido:', $('lista').value || 'A-B-C'); if (!n) return;\n  try { await api('/api/recorridos', { nombre: n.trim(), tramos: leer() }); await listar(n.trim()); toast('Recorrido guardado.'); } catch (e) { toast(e.message); } });\n$('bBorrar').addEventListener('click', async () => { const n = $('lista').value; if (!n || !confirm(`¿Borrar el recorrido «${n}»?`)) return;\n  try { await api('/api/recorridos/' + encodeURIComponent(n), null, 'DELETE'); await listar(); toast('Recorrido borrado.'); } catch (e) { toast(e.message); } });\n$('bEjecutar').addEventListener('click', async () => { soltar(false);\n  try { pintar(await api('/api/ejecutar', { nombre: $('lista').value || 'sin nombre', tramos: leer() })); latir(); toast('Recorrido iniciado.'); } catch (e) { toast(e.message); } });\n$('bExportar').addEventListener('click', () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify({ nombre: $('lista').value || 'recorrido', tramos: leer() }, null, 2)], { type: 'application/json' }));\n  a.download = ($('lista').value || 'recorrido') + '.json'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 2000); });\n$('bImportar').addEventListener('click', () => $('archivo').click());\n$('archivo').addEventListener('change', async e => { const f = e.target.files[0]; if (!f) return;\n  try { const d = JSON.parse(await f.text()); mostrar(Array.isArray(d) ? d : d.tramos); toast('Recorrido importado: revísalo y guárdalo.'); } catch (_) { toast('El archivo no es un recorrido válido.'); } e.target.value = ''; });\n\n/* ---------- prueba y registro ---------- */\n$('bPrueba').addEventListener('click', () => api('/api/prueba', { codigo: $('pCod').value, superficie: $('pSup').value, carga_kg: $('pCar').value }).then(() => toast('Datos de la prueba anotados.')).catch(e => toast(e.message)));\n$('bCsv').addEventListener('click', () => { location.href = '/registro.csv'; });\nasync function registro() {\n  try { const r = await (await fetch('/api/registro?n=25', { cache: 'no-store' })).json();\n    $('reg').innerHTML = r.slice().reverse().map(x => `${x.fecha_hora.slice(11, 23)} · ${x.evento}${x.izq || x.der ? ` (${x.izq}, ${x.der})` : ''}`.replace(/</g, '&lt;')).join('<br>'); } catch (_) { }\n}\nsetInterval(registro, 1500); registro();\n\nlistar().then(() => { const n = $('lista').value; mostrar(guardados[n] || [{ tipo: 'avanzar', velocidad: 60, duracion: 2 }]); });\n</script>\n</body>\n</html>\n"
 },
 {
  "name": "config.json",
  "desc": "Configuración",
  "text": "{\n  \"puerto\": 80,\n  \"pwm_hz\": 1000,\n  \"timeout_ms\": 800,\n  \"factor_izq\": 1.0,\n  \"factor_der\": 1.0,\n  \"toma_control_s\": 3.0\n}\n"
 },
 {
  "name": "instalar.sh",
  "desc": "Instalador",
  "text": "#!/bin/bash\n# Instala el control del UGV de orugas en una Raspberry Pi 3 Model B con Raspberry Pi OS (Bookworm).\n# Uso, dentro de la carpeta raspberry/:   sudo ./instalar.sh\n# Opcional:   sudo SSID=MiUGV CLAVE=otraClave123 ./instalar.sh\nset -euo pipefail\n\n[ \"$(id -u)\" -eq 0 ] || { echo \"Ejecuta con sudo:  sudo ./instalar.sh\"; exit 1; }\ncd \"$(dirname \"$0\")\"\n\nDEST=/opt/ugv\nSSID=\"${SSID:-UGV-Orugas}\"\nCLAVE=\"${CLAVE:-orugas2026}\"          # mínimo 8 caracteres (WPA2)\nCFG=/boot/firmware/config.txt\n[ -f \"$CFG\" ] || CFG=/boot/config.txt  # versiones anteriores a Bookworm\n\necho \"1/5  Paquetes (gpiozero ya viene en Raspberry Pi OS)\"\napt-get update -qq\napt-get install -y -qq python3 python3-gpiozero python3-lgpio\n\necho \"2/5  PWM por hardware en GPIO 12 (ENA) y GPIO 13 (ENB)\"\n# GPIO 12 = PWM0 y GPIO 13 = PWM1 en su función ALT0 (func=4). El audio analógico usa los mismos canales PWM.\nif ! grep -q '^dtoverlay=pwm-2chan' \"$CFG\"; then\n  echo 'dtoverlay=pwm-2chan,pin=12,func=4,pin2=13,func2=4' >> \"$CFG\"\nfi\nsed -i 's/^dtparam=audio=on/dtparam=audio=off/' \"$CFG\"\ngrep -q '^dtparam=audio=off' \"$CFG\" || echo 'dtparam=audio=off' >> \"$CFG\"\n\necho \"3/5  Programa en $DEST\"\nmkdir -p \"$DEST\"\ncp ugv.py \"$DEST/\"\ncp -r web \"$DEST/\"\n[ -f \"$DEST/config.json\" ] || cp config.json \"$DEST/\"\n\necho \"4/5  Servicio que arranca al encender\"\ncp ugv.service /etc/systemd/system/ugv.service\nsystemctl daemon-reload\nsystemctl enable ugv.service\n\necho \"5/5  Red Wi-Fi propia del vehículo: $SSID\"\nraspi-config nonint do_wifi_country CO || true\nnmcli connection delete ugv-ap >/dev/null 2>&1 || true\nnmcli connection add type wifi ifname wlan0 con-name ugv-ap autoconnect yes ssid \"$SSID\" \\\n  connection.autoconnect-priority 100 \\\n  802-11-wireless.mode ap 802-11-wireless.band bg \\\n  ipv4.method shared ipv4.addresses 10.42.0.1/24 \\\n  wifi-sec.key-mgmt wpa-psk wifi-sec.proto rsn wifi-sec.pairwise ccmp wifi-sec.group ccmp wifi-sec.psk \"$CLAVE\"\n\ncat <<FIN\n\nListo. Reinicia la Raspberry Pi:   sudo reboot\nDespués:\n  1. Conecta el celular a la red Wi-Fi «$SSID» (clave: $CLAVE).\n  2. Abre en el navegador:  http://10.42.0.1\nVer el programa en marcha:   journalctl -u ugv -f\nRegistros de las pruebas:    $DEST/registros/\nFIN\n"
 },
 {
  "name": "ugv.service",
  "desc": "Servicio de arranque",
  "text": "[Unit]\nDescription=Control del UGV de orugas (Raspberry Pi 3 + L298N)\nAfter=NetworkManager.service\nWants=NetworkManager.service\n\n[Service]\nType=simple\nWorkingDirectory=/opt/ugv\nExecStart=/usr/bin/python3 /opt/ugv/ugv.py\n# Si el programa falla, se reinicia y lo primero que hace es poner los motores en cero.\nRestart=on-failure\nRestartSec=2\nKillSignal=SIGTERM\nTimeoutStopSec=5\nUser=root\n\n[Install]\nWantedBy=multi-user.target\n"
 },
 {
  "name": "README.md",
  "desc": "Instrucciones",
  "text": "# Programa de la Raspberry Pi\n\nControl real del prototipo: la **Raspberry Pi 3 Model B controla directamente el puente H L298N** (diseño final, sin ESP32). Un solo programa en Python, sin librerías externas (solo `gpiozero`, que ya viene en Raspberry Pi OS):\n\n| Archivo | Qué hace |\n| --- | --- |\n| `ugv.py` | Servidor web, control de motores con PWM por hardware, recorridos por tramos, parada sin órdenes y registro CSV |\n| `web/index.html` | Página de control que se abre en el celular (flechas, velocidad, recorridos, datos de la prueba y registro) |\n| `config.json` | Puerto, frecuencia de la PWM, tiempo de parada sin órdenes y factor de ajuste de cada motor |\n| `ugv.service` | Servicio de systemd: arranca el programa al encender |\n| `instalar.sh` | Instala todo: PWM por hardware, programa, servicio y red Wi-Fi propia |\n| `test_ugv.py` | Pruebas de extremo a extremo con los pines simulados |\n\n## Conexiones (diagrama final)\n\n| Raspberry Pi | Pin físico | L298N | Función |\n| --- | --- | --- | --- |\n| 5V | 2 | — | Entra la salida de 5 V del DC-DC |\n| GND | 6 | GND | Tierra común con las baterías, el DC-DC y el L298N |\n| GPIO 12 | 32 | ENA | PWM por hardware del motor A (izquierdo) |\n| GPIO 17 | 11 | IN1 | Sentido del motor A |\n| GPIO 27 | 13 | IN2 | Sentido del motor A |\n| GPIO 22 | 15 | IN3 | Sentido del motor B |\n| GPIO 23 | 16 | IN4 | Sentido del motor B |\n| GPIO 13 | 33 | ENB | PWM por hardware del motor B (derecho) |\n\nBaterías 7,4 V (+) → bornera 12V del L298N y entrada del DC-DC. OUT1/OUT2 → motor A; OUT3/OUT4 → motor B. **La salida de 5 V del L298N no se usa.** Quita los puentes (jumpers) de ENA y ENB del módulo para que esos pines reciban la PWM de la Raspberry Pi.\n\n## Instalación paso a paso\n\n1. Graba **Raspberry Pi OS Lite (64 bits, Bookworm)** en la microSD con *Raspberry Pi Imager*. En la configuración del Imager activa **SSH**, pon usuario y clave y, para la instalación, la red Wi-Fi de tu casa.\n2. Enciende la Raspberry Pi, entra por SSH (`ssh usuario@raspberrypi.local`) y copia esta carpeta. Por ejemplo, desde el computador:\n   ```bash\n   scp -r raspberry usuario@raspberrypi.local:~/\n   ```\n3. En la Raspberry Pi:\n   ```bash\n   cd ~/raspberry\n   chmod +x instalar.sh\n   sudo ./instalar.sh\n   sudo reboot\n   ```\n   El instalador agrega a `config.txt` la PWM por hardware (`dtoverlay=pwm-2chan,pin=12,func=4,pin2=13,func2=4` y `dtparam=audio=off`), copia el programa a `/opt/ugv`, activa el servicio y crea la red **UGV-Orugas** (clave `orugas2026`). Para otro nombre o clave: `sudo SSID=MiUGV CLAVE=otraClave123 ./instalar.sh`.\n4. Después de reiniciar, conecta el celular a la red **UGV-Orugas** y abre **http://10.42.0.1**.\n\n> Después del paso 3 la Raspberry Pi crea su propia red y deja de conectarse a la de tu casa. Para volver a entrar por SSH, conecta el computador a **UGV-Orugas** y usa `ssh usuario@10.42.0.1`.\n\n## Uso\n\n- **Control remoto:** mantén pulsada una flecha; al soltarla se detiene. **ALTO** y **PARAR** detienen en cualquier momento, desde cualquier celular.\n- **Recorrido programado:** lista de tramos (avanzar, retroceder, girar a la izquierda o a la derecha sobre su eje, pausa), cada uno con velocidad (%) y duración (s). Se ejecuta en **lazo abierto**: cumple los tiempos sin medir la posición. La página debe quedar abierta mientras corre.\n- **Parada sin órdenes:** si dejan de llegar órdenes del celular durante `timeout_ms` (800 ms por defecto), el programa detiene los motores y queda en «DETENIDO POR SEGURIDAD».\n- **Datos de la prueba:** elige el código (P1–P10), la superficie y la carga antes de cada ensayo; quedan en cada línea del registro.\n- **Registro:** `/opt/ugv/registros/registro-AAAA-MM-DD.csv` (también se descarga desde la página).\n- **Ajuste de motores:** si en la prueba P2 el vehículo se desvía siempre hacia un lado, baja el factor del motor más rápido en `/opt/ugv/config.json` (por ejemplo `\"factor_der\": 0.95`) y reinicia el servicio: `sudo systemctl restart ugv`.\n\nComandos útiles:\n\n```bash\njournalctl -u ugv -f          # ver lo que hace el programa\nsudo systemctl stop ugv       # detenerlo (los motores quedan apagados)\nsudo systemctl restart ugv    # reiniciarlo después de cambiar config.json\n```\n\n## Probar sin la Raspberry Pi\n\nEn cualquier computador con Python 3:\n\n```bash\npython3 raspberry/ugv.py --simular            # abre http://localhost:8080\npython3 -m unittest raspberry/test_ugv.py     # 12 pruebas del servidor real con pines simulados\n```\n\n## Limitación de seguridad (declarada en el informe)\n\nLa parada sin órdenes vive en este mismo programa. **Si el programa o el sistema operativo se bloquean, los pines pueden quedar en su último estado y los motores seguir girando.** El corte total del prototipo es **desconectar la batería**; para versiones futuras se recomienda un interruptor o paro físico que corte la potencia de los motores sin depender del software. Si el programa termina normalmente o por un error, primero pone los motores en cero, y el servicio lo vuelve a iniciar a los 2 s.\n\n## API (para pruebas o para otros programas)\n\n| Método y ruta | Cuerpo JSON | Respuesta |\n| --- | --- | --- |\n| `GET /api/estado?cliente=id` | — | modo, potencia de cada oruga, recorrido en curso, pines |\n| `POST /api/mover` | `{\"cliente\", \"izq\", \"der\"}` de −100 a 100 | estado (409 si otro dispositivo maneja) |\n| `POST /api/parar` | `{\"cliente\"}` | estado |\n| `POST /api/latido` | `{\"cliente\"}` | estado (mantiene vivo un recorrido) |\n| `GET /api/recorridos` | — | recorridos guardados |\n| `POST /api/recorridos` | `{\"nombre\", \"tramos\": [{\"tipo\", \"velocidad\", \"duracion\"}]}` | estado |\n| `DELETE /api/recorridos/<nombre>` | — | `{\"ok\": true}` |\n| `POST /api/ejecutar` | `{\"cliente\", \"nombre\"}` o `{\"cliente\", \"nombre\", \"tramos\"}` | estado |\n| `POST /api/prueba` | `{\"codigo\", \"superficie\", \"carga_kg\"}` | estado |\n| `GET /api/registro?n=30` · `GET /registro.csv` | — | últimas líneas · archivo del día |\n\n## Si algo no funciona\n\n| Síntoma | Causa probable |\n| --- | --- |\n| El registro dice «PWM software» | Falta el overlay en `config.txt` o no se reinició; revisa con `ls /sys/class/pwm/pwmchip0` |\n| Un motor gira al revés | Intercambia sus dos cables en OUT1/OUT2 (o OUT3/OUT4) |\n| Un motor no gira | El puente de ENA o ENB sigue puesto, o falta la tierra común entre la Raspberry Pi y el L298N |\n| La Raspberry Pi se reinicia al arrancar los motores | Alimentación: revisa que el DC-DC entregue 5 V y soporte la corriente; no uses el 5 V del L298N |\n| No aparece la red UGV-Orugas | Revisa `nmcli connection show` y el país Wi-Fi (`sudo raspi-config` → Localisation → WLAN Country) |\n"
 },
 {
  "name": "test_ugv.py",
  "desc": "Pruebas",
  "text": "\"\"\"Pruebas de extremo a extremo del programa de la Raspberry Pi, con los pines simulados.\n\nArrancan el servidor real en un puerto libre y lo usan como lo haría el celular:\n    python -m unittest raspberry/test_ugv.py\n\"\"\"\nimport json\nimport os\nimport shutil\nimport sys\nimport tempfile\nimport threading\nimport time\nimport unittest\nimport urllib.error\nimport urllib.request\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport ugv  # noqa: E402\n\n\nclass PruebasUGV(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.tmp = tempfile.mkdtemp()\n        cls.srv, cls.ctl = ugv.crear(simular=True, puerto=0, carpeta=cls.tmp)\n        cls.ctl.cfg[\"timeout_ms\"] = 300\n        cls.base = f\"http://127.0.0.1:{cls.srv.server_address[1]}\"\n        threading.Thread(target=cls.srv.serve_forever, daemon=True).start()\n\n    @classmethod\n    def tearDownClass(cls):\n        cls.srv.shutdown()\n        cls.ctl.cerrar()\n        cls.srv.server_close()\n        shutil.rmtree(cls.tmp, ignore_errors=True)\n\n    def setUp(self):\n        self.post(\"/api/parar\", {\"cliente\": \"a\"})\n        self.ctl.duenio = None\n        self.ctl.modo = ugv.ESPERA\n\n    def pedir(self, ruta, cuerpo=None, metodo=None):\n        datos = json.dumps(cuerpo).encode() if cuerpo is not None else None\n        req = urllib.request.Request(self.base + ruta, data=datos, method=metodo or (\"POST\" if datos else \"GET\"),\n                                     headers={\"Content-Type\": \"application/json\"})\n        try:\n            with urllib.request.urlopen(req, timeout=3) as r:\n                return r.status, r.read()\n        except urllib.error.HTTPError as e:\n            return e.code, e.read()\n\n    def post(self, ruta, cuerpo):\n        codigo, datos = self.pedir(ruta, cuerpo)\n        return codigo, json.loads(datos)\n\n    def estado(self):\n        return json.loads(self.pedir(\"/api/estado\")[1])\n\n    def test_pagina_de_control(self):\n        codigo, html = self.pedir(\"/\")\n        self.assertEqual(codigo, 200)\n        self.assertIn(\"UGV de orugas\", html.decode(\"utf-8\"))\n\n    def test_avanzar_fija_pines_del_l298n(self):\n        codigo, e = self.post(\"/api/mover\", {\"cliente\": \"a\", \"izq\": 60, \"der\": 60})\n        self.assertEqual(codigo, 200)\n        self.assertEqual(e[\"modo\"], ugv.REMOTO)\n        p = e[\"pines\"]\n        self.assertEqual((p[\"IN1\"], p[\"IN2\"], p[\"IN3\"], p[\"IN4\"]), (True, False, True, False))\n        self.assertAlmostEqual(p[\"ENA\"], 0.6)\n        self.assertAlmostEqual(p[\"ENB\"], 0.6)\n\n    def test_giro_en_el_sitio_invierte_una_oruga(self):\n        _, e = self.post(\"/api/mover\", {\"cliente\": \"a\", \"izq\": -50, \"der\": 50})\n        p = e[\"pines\"]\n        self.assertEqual((p[\"IN1\"], p[\"IN2\"]), (False, True))   # motor A hacia atrás\n        self.assertEqual((p[\"IN3\"], p[\"IN4\"]), (True, False))   # motor B hacia adelante\n        self.assertAlmostEqual(p[\"ENA\"], 0.5)\n\n    def test_parada_si_dejan_de_llegar_ordenes(self):\n        self.post(\"/api/mover\", {\"cliente\": \"a\", \"izq\": 80, \"der\": 80})\n        time.sleep(0.15)\n        self.assertEqual(self.estado()[\"izq\"], 80)\n        time.sleep(0.45)\n        e = self.estado()\n        self.assertEqual(e[\"modo\"], ugv.SEGURIDAD)\n        self.assertEqual((e[\"izq\"], e[\"der\"], e[\"pines\"][\"ENA\"], e[\"pines\"][\"ENB\"]), (0, 0, 0, 0))\n\n    def test_otro_celular_no_puede_manejar_pero_si_detener(self):\n        self.post(\"/api/mover\", {\"cliente\": \"a\", \"izq\": 40, \"der\": 40})\n        codigo, e = self.post(\"/api/mover\", {\"cliente\": \"b\", \"izq\": 90, \"der\": 90})\n        self.assertEqual(codigo, 409)\n        codigo, e = self.post(\"/api/parar\", {\"cliente\": \"b\"})\n        self.assertEqual((codigo, e[\"izq\"], e[\"der\"]), (200, 0, 0))\n\n    def test_recorrido_por_tramos_con_latido(self):\n        tramos = [{\"tipo\": \"avanzar\", \"velocidad\": 50, \"duracion\": 0.4}, {\"tipo\": \"derecha\", \"velocidad\": 40, \"duracion\": 0.4}]\n        codigo, e = self.post(\"/api/ejecutar\", {\"cliente\": \"a\", \"nombre\": \"prueba\", \"tramos\": tramos})\n        self.assertEqual((codigo, e[\"modo\"]), (200, ugv.RECORRIDO))\n        vistos, fin = set(), time.time() + 2\n        while time.time() < fin:\n            self.post(\"/api/latido\", {\"cliente\": \"a\"})\n            e = self.estado()\n            if e[\"recorrido\"]:\n                vistos.add((e[\"recorrido\"][\"tipo\"], e[\"izq\"], e[\"der\"]))\n            elif e[\"modo\"] == ugv.ESPERA:\n                break\n            time.sleep(0.05)\n        self.assertIn((\"avanzar\", 50, 50), vistos)\n        self.assertIn((\"derecha\", 40, -40), vistos)\n        self.assertEqual((e[\"modo\"], e[\"izq\"], e[\"der\"]), (ugv.ESPERA, 0, 0))\n\n    def test_recorrido_se_detiene_sin_latido(self):\n        self.post(\"/api/ejecutar\", {\"cliente\": \"a\", \"nombre\": \"largo\", \"tramos\": [{\"tipo\": \"avanzar\", \"velocidad\": 70, \"duracion\": 5}]})\n        time.sleep(0.6)\n        e = self.estado()\n        self.assertEqual((e[\"modo\"], e[\"izq\"]), (ugv.SEGURIDAD, 0))\n\n    def test_parar_interrumpe_el_recorrido(self):\n        self.post(\"/api/ejecutar\", {\"cliente\": \"a\", \"nombre\": \"largo\", \"tramos\": [{\"tipo\": \"avanzar\", \"velocidad\": 70, \"duracion\": 5}]})\n        time.sleep(0.1)\n        _, e = self.post(\"/api/parar\", {\"cliente\": \"a\"})\n        self.assertEqual((e[\"modo\"], e[\"izq\"], e[\"recorrido\"]), (ugv.ESPERA, 0, None))\n\n    def test_valida_los_tramos(self):\n        malos = [[], [{\"tipo\": \"saltar\", \"velocidad\": 10, \"duracion\": 1}], [{\"tipo\": \"avanzar\", \"velocidad\": 120, \"duracion\": 1}],\n                 [{\"tipo\": \"avanzar\", \"velocidad\": 50, \"duracion\": 0}], [{\"tipo\": \"avanzar\", \"velocidad\": 50}]]\n        for t in malos:\n            codigo, e = self.post(\"/api/ejecutar\", {\"cliente\": \"a\", \"nombre\": \"x\", \"tramos\": t})\n            self.assertEqual(codigo, 400, t)\n            self.assertIn(\"error\", e)\n\n    def test_guardar_listar_y_borrar_recorridos(self):\n        tramos = [{\"tipo\": \"avanzar\", \"velocidad\": 60, \"duracion\": 2.5}, {\"tipo\": \"pausa\", \"velocidad\": 0, \"duracion\": 1}]\n        self.assertEqual(self.post(\"/api/recorridos\", {\"nombre\": \"Ruta tierra\", \"tramos\": tramos})[0], 200)\n        todos = json.loads(self.pedir(\"/api/recorridos\")[1])\n        self.assertEqual(todos[\"Ruta tierra\"], tramos)\n        self.assertIn(\"A-B-C\", todos)\n        self.assertEqual(self.pedir(\"/api/recorridos/Ruta%20tierra\", metodo=\"DELETE\")[0], 200)\n        self.assertNotIn(\"Ruta tierra\", json.loads(self.pedir(\"/api/recorridos\")[1]))\n        self.assertEqual(self.post(\"/api/ejecutar\", {\"cliente\": \"a\", \"nombre\": \"no-existe\"})[0], 404)\n\n    def test_registro_csv_con_datos_de_la_prueba(self):\n        self.post(\"/api/prueba\", {\"cliente\": \"a\", \"codigo\": \"P2\", \"superficie\": \"tierra\", \"carga_kg\": \"1\"})\n        self.post(\"/api/mover\", {\"cliente\": \"a\", \"izq\": 30, \"der\": 30})\n        self.post(\"/api/parar\", {\"cliente\": \"a\"})\n        codigo, csv = self.pedir(\"/registro.csv\")\n        lineas = csv.decode(\"utf-8\").splitlines()\n        self.assertEqual(lineas[0], \"fecha_hora,modo,evento,izq,der,prueba,superficie,carga_kg\")\n        self.assertTrue(any(\",P2,tierra,1\" in l and \",30,30,\" in l for l in lineas))\n\n    def test_factor_de_ajuste_de_un_motor(self):\n        self.ctl.cfg[\"factor_der\"] = 0.9\n        try:\n            _, e = self.post(\"/api/mover\", {\"cliente\": \"a\", \"izq\": 100, \"der\": 100})\n            self.assertEqual((e[\"izq\"], e[\"der\"]), (100, 90))\n        finally:\n            self.ctl.cfg[\"factor_der\"] = 1.0\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n"
 }
